import { useEffect, useMemo, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useSearchParams } from "react-router-dom";
import { Activity, Bot, BookOpen, BrainCircuit, Check, Clock3, ExternalLink, GitBranch, LoaderCircle, MessageSquareText, Plus, PlugZap, RefreshCw, Search, ShieldCheck, Sparkles, Target, Trash2, TriangleAlert } from "lucide-react";
import { useWorkspace } from "../context/WorkspaceContext";
import { useProjects } from "../hooks/useProjects";
import { useTasks } from "../hooks/useTasks";
import { getExecutionGraph } from "../api/execution";
import { addKnowledgeDocument, createRecoveryPlan, createScenario, decideRecoveryPlan, deleteIntegration, deleteKnowledgeDocument, getAgentRuns, getAnalytics, getIntegrationEvents, getIntegrationProviders, getIntegrations, getKnowledgeDocuments, getRecoveryPlans, getScenarios, queueIntegrationSync, runAgent, runScenario, saveAnalyticsSnapshot, searchKnowledge, startIntegration, type AgentRun, type ExecutionAnalytics, type ExternalIntegration, type IntegrationEvent, type IntegrationProvider, type RecoveryPlan } from "../api/intelligence";

type Tab = "analytics" | "scenarios" | "recovery" | "agents" | "knowledge" | "integrations";
const tabs: Array<{ id: Tab; label: string; icon: typeof Activity }> = [
  { id: "analytics", label: "Analytics", icon: Activity },
  { id: "scenarios", label: "What if?", icon: GitBranch },
  { id: "recovery", label: "Recovery", icon: ShieldCheck },
  { id: "agents", label: "Agents", icon: Bot },
  { id: "knowledge", label: "Knowledge", icon: BookOpen },
  { id: "integrations", label: "Integrations", icon: PlugZap },
];
const panel = "rounded-2xl border border-slate-200 bg-white p-5 shadow-sm";
const button = "inline-flex items-center justify-center gap-2 rounded-xl bg-violet-600 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-violet-700 disabled:cursor-not-allowed disabled:opacity-50";
const subtleButton = "inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50";
const field = "w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm text-slate-800 outline-none transition placeholder:text-slate-400 focus:border-violet-400 focus:ring-2 focus:ring-violet-100";
const dateLabel = (value?: string | null) => value ? new Date(value).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" }) : "No deadline";
const titleCase = (value: string) => value.toLowerCase().replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());

function AnalyticsView({ analytics, saving, onSave }: { analytics: ExecutionAnalytics; saving: boolean; onSave: () => void }) {
  const maxLoad = Math.max(1, ...analytics.workload.map((person) => person.openTasks));
  return <div className="space-y-5">
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      {[
        { label: "Open tasks", value: analytics.openCount, detail: `${analytics.completedCount} complete`, icon: Target, color: "text-violet-600 bg-violet-50" },
        { label: "Critical path", value: `${analytics.graph.estimatedDurationDays}d`, detail: `${analytics.graph.criticalPath.length} critical tasks`, icon: GitBranch, color: "text-blue-700 bg-blue-50" },
        { label: "Blocked time", value: analytics.blockedTime.p50Days === null ? "—" : `${analytics.blockedTime.p50Days}d`, detail: `${analytics.blockedTime.sampleCount} blocked periods`, icon: Clock3, color: "text-amber-700 bg-amber-50" },
        { label: "Cycle time", value: analytics.cycleTime.p50Days === null ? "—" : `${analytics.cycleTime.p50Days}d`, detail: `${analytics.cycleTime.sampleCount} completed samples`, icon: Activity, color: "text-emerald-700 bg-emerald-50" },
      ].map(({ label, value, detail, icon: Icon, color }) => <article key={label} className={`${panel} p-4`}><div className="flex items-center justify-between"><span className="text-sm text-slate-500">{label}</span><span className={`flex h-9 w-9 items-center justify-center rounded-xl ${color}`}><Icon size={17}/></span></div><p className="mt-4 text-2xl font-bold tracking-tight text-slate-950">{value}</p><p className="mt-1 text-xs text-slate-500">{detail}</p></article>)}
    </div>
    <div className="grid gap-5 xl:grid-cols-2">
      <section className={panel}><div className="mb-4 flex items-start justify-between gap-4"><div><h2 className="font-semibold text-slate-900">Critical path</h2><p className="mt-1 text-xs text-slate-500">Tasks with no schedule slack, based on saved durations.</p></div><button className={subtleButton} onClick={onSave} disabled={saving}><Check size={15}/>{saving ? "Saving…" : "Save snapshot"}</button></div>
        {analytics.graph.criticalPath.length ? <ol className="space-y-2">{analytics.graph.criticalPath.slice(0, 8).map((task, index) => <li key={task.taskId} className="flex items-center gap-3 rounded-xl bg-violet-50/70 p-3"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-white text-xs font-bold text-violet-700">{index + 1}</span><span className="min-w-0 flex-1 truncate text-sm font-medium text-slate-800">{task.title}</span><span className="text-xs tabular-nums text-slate-500">day {task.earliestStartDay}–{task.earliestFinishDay}</span></li>)}</ol> : <div className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">Add tasks and connect dependencies to calculate a critical path.</div>}
      </section>
      <section className={panel}><div className="mb-4"><h2 className="font-semibold text-slate-900">Member workload</h2><p className="mt-1 text-xs text-slate-500">Open tasks and blocked work by assignee.</p></div>
        {analytics.workload.length ? <div className="space-y-4">{analytics.workload.slice(0, 8).map((person) => <div key={person.personId}><div className="mb-1.5 flex items-center justify-between text-sm"><span className="truncate font-medium text-slate-700">{person.name}</span><span className="text-xs text-slate-500">{person.openTasks} open · {person.blockedTasks} blocked</span></div><div className="h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-violet-500 transition-all" style={{ width: `${Math.max(6, person.openTasks / maxLoad * 100)}%` }}/></div></div>)}</div> : <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">Assign tasks to members to see workload.</p>}
      </section>
    </div>
    <div className="grid gap-5 xl:grid-cols-2">
      <section className={panel}><h2 className="font-semibold text-slate-900">Bottlenecks</h2><p className="mb-4 mt-1 text-xs text-slate-500">Current signals from dependencies, overdue dates, and task status.</p>{analytics.bottlenecks.length ? <div className="space-y-2">{analytics.bottlenecks.slice(0, 6).map((item) => <div key={`${item.taskId}-${item.reason}`} className="flex items-center gap-3 rounded-xl border border-slate-100 p-3"><TriangleAlert size={16} className={item.severity === "HIGH" ? "text-rose-500" : "text-amber-500"}/><span className="min-w-0 flex-1 truncate text-sm font-medium text-slate-700">{item.title}</span><span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-semibold uppercase text-slate-500">{titleCase(item.reason)}</span></div>)}</div> : <p className="rounded-xl bg-emerald-50 p-4 text-sm text-emerald-800">No bottlenecks detected from the available data.</p>}</section>
      <section className={panel}><h2 className="font-semibold text-slate-900">Plan accuracy</h2><p className="mb-4 mt-1 text-xs text-slate-500">Actual completion compared with saved plan dates.</p>{analytics.historicalPatterns.sampleCount ? <><p className="text-3xl font-bold text-slate-950">{analytics.historicalPatterns.averageVarianceDays! > 0 ? "+" : ""}{analytics.historicalPatterns.averageVarianceDays} <span className="text-sm font-medium text-slate-500">days average</span></p><div className="mt-4 space-y-2">{analytics.historicalPatterns.plannedActual.slice(0, 4).map((item) => <div key={item.taskId} className="flex items-center justify-between gap-3 border-t border-slate-100 pt-2 text-xs"><span className="truncate text-slate-600">{item.title}</span><span className={item.varianceDays > 0 ? "shrink-0 font-semibold text-rose-600" : "shrink-0 font-semibold text-emerald-700"}>{item.varianceDays > 0 ? "+" : ""}{item.varianceDays}d</span></div>)}</div></> : <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">Save an execution plan and complete tasks to learn from historical estimates.</p>}</section>
    </div>
  </div>;
}

function ScenarioView({ scenarios, tasks, canWrite, onCreate, creating, onRun, runningId }: { scenarios: Array<{ id: string; name: string; changes: Record<string, unknown>; latest_run: { id: string; createdAt: string; result: { scenario: { finishDate: string; delayDays: number; deadlineStatus: string }; baseline: { finishDate: string } } } | null }>; tasks: Array<{ id: string; title: string }>; canWrite: boolean; onCreate: (payload: { name: string; changes: Record<string, unknown> }) => void; creating: boolean; onRun: (id: string) => void; runningId: string | null }) {
  const [name, setName] = useState("");
  const [taskId, setTaskId] = useState("");
  const [delayDays, setDelayDays] = useState(3);
  return <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]">
    {canWrite && <section className={panel}><div className="mb-4 flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-blue-700"><GitBranch size={18}/></span><div><h2 className="font-semibold text-slate-900">Create a what-if plan</h2><p className="text-xs text-slate-500">Try a delay without changing project tasks.</p></div></div><form className="space-y-3" onSubmit={(event) => { event.preventDefault(); const changes = taskId ? { taskDelays: { [taskId]: delayDays } } : {}; onCreate({ name: name.trim() || `Delay scenario · ${delayDays} days`, changes }); setName(""); }}><label className="block text-xs font-semibold text-slate-500">Scenario name<input className={`${field} mt-1.5`} value={name} onChange={(event) => setName(event.target.value)} placeholder="What if the design review slips?" maxLength={120}/></label><label className="block text-xs font-semibold text-slate-500">Task<select className={`${field} mt-1.5`} value={taskId} onChange={(event) => setTaskId(event.target.value)}><option value="">No specific task</option>{tasks.map((task) => <option key={task.id} value={task.id}>{task.title}</option>)}</select></label><label className="block text-xs font-semibold text-slate-500">Delay in business days<input className={`${field} mt-1.5`} type="number" min={0} max={365} value={delayDays} onChange={(event) => setDelayDays(Number(event.target.value))}/></label><button className={button} disabled={creating}><Plus size={15}/>{creating ? "Saving…" : "Save scenario"}</button></form><p className="mt-4 text-xs leading-5 text-slate-500">Simulations are deterministic and read-only. They use current dependencies and planned task durations.</p></section>}
    <section className={panel}><div className="mb-4"><h2 className="font-semibold text-slate-900">Saved scenarios</h2><p className="mt-1 text-xs text-slate-500">Run again after the project plan changes to compare a fresh snapshot.</p></div>{scenarios.length ? <div className="space-y-3">{scenarios.map((scenario) => <article key={scenario.id} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-semibold text-slate-800">{scenario.name}</h3><p className="mt-1 text-xs text-slate-500">{scenario.latest_run ? `Last run ${new Date(scenario.latest_run.createdAt).toLocaleString()}` : "Not run yet"}</p></div><button className={subtleButton} onClick={() => onRun(scenario.id)} disabled={!canWrite || runningId === scenario.id}>{runningId === scenario.id ? <LoaderCircle size={14} className="animate-spin"/> : <Activity size={14}/>}Run simulation</button></div>{scenario.latest_run && <div className="mt-4 grid gap-3 rounded-xl bg-slate-50 p-3 text-sm sm:grid-cols-3"><div><span className="block text-[10px] uppercase tracking-wide text-slate-400">Baseline finish</span><strong className="mt-1 block text-slate-800">{dateLabel(scenario.latest_run.result.baseline.finishDate)}</strong></div><div><span className="block text-[10px] uppercase tracking-wide text-slate-400">Scenario finish</span><strong className="mt-1 block text-slate-800">{dateLabel(scenario.latest_run.result.scenario.finishDate)}</strong></div><div><span className="block text-[10px] uppercase tracking-wide text-slate-400">Finish change</span><strong className={scenario.latest_run.result.scenario.delayDays > 0 ? "mt-1 block text-rose-600" : "mt-1 block text-emerald-700"}>{scenario.latest_run.result.scenario.delayDays > 0 ? "+" : ""}{scenario.latest_run.result.scenario.delayDays} days</strong></div></div>}</article>)}</div> : <p className="rounded-xl bg-slate-50 p-5 text-center text-sm text-slate-500">No scenarios yet. Start with a task delay to see the schedule impact.</p>}</section>
  </div>;
}

function RecoveryView({ plans, canWrite, creating, onCreate, onDecision }: { plans: RecoveryPlan[]; canWrite: boolean; creating: boolean; onCreate: () => void; onDecision: (input: { planId: string; decision: "APPROVE" | "REJECT"; optionKey?: string }) => void }) {
  const [selected, setSelected] = useState<Record<string, string>>({});
  return <div className="space-y-5"><section className={`${panel} flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between`}><div><div className="flex items-center gap-2"><ShieldCheck size={19} className="text-violet-600"/><h2 className="font-semibold text-slate-900">Recovery options</h2></div><p className="mt-1 text-xs leading-5 text-slate-500">Generate safe candidates from delivery risks. A reviewer must choose and approve any change.</p></div><button className={button} disabled={!canWrite || creating} onClick={onCreate}><Sparkles size={15}/>{creating ? "Analyzing…" : "Find recovery options"}</button></section>
    {plans.length ? <div className="space-y-4">{plans.map((plan) => <article key={plan.id} className={panel}><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-semibold text-slate-900">{plan.name}</h3><p className="mt-1 text-xs text-slate-500">Created {new Date(plan.created_at).toLocaleString()}</p></div><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${plan.status === "PENDING" ? "bg-amber-50 text-amber-800" : plan.status === "SUCCEEDED" ? "bg-emerald-50 text-emerald-800" : "bg-slate-100 text-slate-600"}`}>{titleCase(plan.status)}</span></div><div className="mt-3 flex flex-wrap gap-2 text-xs"><span className="rounded-lg bg-slate-50 px-2.5 py-1.5 text-slate-600">Health: {plan.root_cause?.health?.score ?? "—"}/100</span><span className="rounded-lg bg-slate-50 px-2.5 py-1.5 text-slate-600">{plan.root_cause?.health?.label ? titleCase(plan.root_cause.health.label) : "Health review"}</span></div><div className="mt-4 grid gap-3 lg:grid-cols-2">{plan.options.map((option) => <div key={option.key} className={`rounded-xl border p-4 ${selected[plan.id] === option.key ? "border-violet-400 bg-violet-50/60" : "border-slate-100"}`}><div className="flex items-start justify-between gap-3"><h4 className="text-sm font-semibold text-slate-800">{option.title}</h4><span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-semibold uppercase text-slate-500">{option.executable ? "Action" : "Review"}</span></div><p className="mt-2 text-xs leading-5 text-slate-500">{option.explanation}</p><p className="mt-2 text-[11px] font-medium text-amber-700">{option.risk}</p>{option.executable && <button disabled={!canWrite || plan.status !== "PENDING"} onClick={() => setSelected((previous) => ({ ...previous, [plan.id]: option.key }))} className={`mt-3 rounded-lg px-3 py-1.5 text-xs font-semibold ${selected[plan.id] === option.key ? "bg-violet-600 text-white" : "border border-slate-200 text-slate-600 hover:bg-slate-50"}`}>{selected[plan.id] === option.key ? "Selected" : "Choose this option"}</button>}</div>)}</div>{plan.status === "PENDING" && <div className="mt-4 flex flex-wrap justify-end gap-2"><button className={subtleButton} disabled={!canWrite} onClick={() => onDecision({ planId: plan.id, decision: "REJECT" })}>Reject plan</button><button className={button} disabled={!canWrite || !selected[plan.id]} onClick={() => onDecision({ planId: plan.id, decision: "APPROVE", optionKey: selected[plan.id] })}><Check size={14}/>Approve selected action</button></div>}{plan.status === "SUCCEEDED" && <p className="mt-3 rounded-lg bg-emerald-50 p-3 text-xs text-emerald-800">Applied and verified. Task and dependency changes were committed atomically.</p>}</article>)}</div> : <div className={`${panel} py-10 text-center`}><ShieldCheck size={26} className="mx-auto text-violet-500"/><p className="mt-3 font-semibold text-slate-800">No recovery plans yet</p><p className="mt-1 text-sm text-slate-500">Generate options when a project needs a plan change.</p></div>}</div>;
}

function AgentsView({ runs, canWrite, running, onRun }: { runs: AgentRun[]; canWrite: boolean; running: boolean; onRun: (payload: { agentType: string; budgetLimit: number; question?: string }) => void }) {
  const [agentType, setAgentType] = useState("COORDINATOR");
  const [question, setQuestion] = useState("");
  const [budgetLimit, setBudgetLimit] = useState(1000);
  return <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><section className={panel}><div className="mb-4 flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-violet-50 text-violet-700"><BrainCircuit size={18}/></span><div><h2 className="font-semibold text-slate-900">Run a project agent</h2><p className="text-xs text-slate-500">Grounded analysis with a saved trace.</p></div></div><form className="space-y-3" onSubmit={(event) => { event.preventDefault(); onRun({ agentType, budgetLimit, ...(question.trim() ? { question: question.trim() } : {}) }); }}><label className="block text-xs font-semibold text-slate-500">Agent<select className={`${field} mt-1.5`} value={agentType} onChange={(event) => setAgentType(event.target.value)}>{["COORDINATOR", "PLANNER", "EVIDENCE", "RISK", "FORECAST", "RECOVERY", "EXECUTION"].map((item) => <option key={item} value={item}>{titleCase(item)}</option>)}</select></label><label className="block text-xs font-semibold text-slate-500">Question (optional)<textarea className={`${field} mt-1.5 min-h-24 resize-y`} value={question} onChange={(event) => setQuestion(event.target.value)} maxLength={500} placeholder="What should the team focus on next?"/></label><label className="block text-xs font-semibold text-slate-500">Work budget<input className={`${field} mt-1.5`} type="number" min={1} max={10000} value={budgetLimit} onChange={(event) => setBudgetLimit(Number(event.target.value))}/><span className="mt-1 block font-normal text-slate-400">A work unit is one task, dependency, or task-history entry examined.</span></label><button className={button} disabled={!canWrite || running}>{running ? <LoaderCircle size={15} className="animate-spin"/> : <Sparkles size={15}/>}Run analysis</button></form><p className="mt-4 flex items-start gap-2 rounded-xl bg-slate-50 p-3 text-xs leading-5 text-slate-500"><ShieldCheck size={15} className="mt-0.5 shrink-0 text-emerald-600"/>Runs are deterministic and read-only. Task changes require a separate review and approval.</p></section>
    <section className={panel}><div className="mb-4"><h2 className="font-semibold text-slate-900">Recent runs</h2><p className="mt-1 text-xs text-slate-500">Each run stores its steps, citations, work budget, and evaluation result.</p></div>{runs.length ? <div className="space-y-3">{runs.map((run) => <details key={run.id} className="rounded-xl border border-slate-100 p-4"><summary className="cursor-pointer list-none"><div className="flex flex-wrap items-center justify-between gap-3"><div><span className="font-semibold text-slate-800">{titleCase(run.agent_type)}</span><span className="ml-2 text-xs text-slate-400">{new Date(run.created_at).toLocaleString()}</span><p className="mt-1 text-sm text-slate-600">{run.result?.summary ?? "Run details unavailable"}</p></div><span className="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-800">{run.budget_used}/{run.budget_limit} units</span></div></summary>{run.result && <div className="mt-4 space-y-3 border-t border-slate-100 pt-4">{run.result.steps.map((step, index) => <div key={`${run.id}-${step.role}`} className="rounded-lg bg-slate-50 p-3"><div className="mb-1 flex items-center gap-2 text-xs font-semibold text-violet-700"><span>{index + 1}.</span>{titleCase(step.role)}</div><div className="space-y-1">{Object.entries(step.result).map(([key, value]) => <p key={key} className="text-xs leading-5 text-slate-600"><strong className="capitalize text-slate-700">{titleCase(key)}:</strong> {typeof value === "string" || typeof value === "number" ? String(value) : Array.isArray(value) ? `${value.length} item${value.length === 1 ? "" : "s"}` : JSON.stringify(value)}</p>)}</div></div>)}<div className="flex flex-wrap items-center gap-2 border-t border-slate-100 pt-3 text-xs text-slate-500"><span>{run.result.citations.length} task citations</span><span>·</span><span>{run.result.safety.mode}</span><span>·</span><span>no changes applied</span></div>{run.evaluations?.[0] && <p className="text-[11px] text-slate-400">Evaluation {run.evaluations[0].passed ? "passed" : "needs review"} · {run.evaluations[0].latency_ms ?? 0}ms</p>}</div>}</details>)}</div> : <p className="rounded-xl bg-slate-50 p-5 text-center text-sm text-slate-500">No agent runs yet. Start with the coordinator for a short project briefing.</p>}</section></div>;
}

function KnowledgeView({ workspaceId, documents, canWrite, saving, deleting, onAdd, onDelete }: { workspaceId: string; documents: Array<{ id: string; title: string; source_type: string; source_url: string | null; chunk_count: number | bigint; created_at: string }>; canWrite: boolean; saving: boolean; deleting: boolean; onAdd: (payload: { title: string; sourceType: string; sourceUrl?: string; content: string }) => void; onDelete: (id: string) => void }) {
  const [title, setTitle] = useState("");
  const [sourceType, setSourceType] = useState("MARKDOWN");
  const [sourceUrl, setSourceUrl] = useState("");
  const [content, setContent] = useState("");
  const [query, setQuery] = useState("");
  const [matches, setMatches] = useState<Array<{ chunk_id: string; document_id: string; title: string; heading: string | null; snippet: string; source_url: string | null }> | null>(null);
  const [retrievalMode, setRetrievalMode] = useState("");
  const search = useMutation({ mutationFn: (value: string) => searchKnowledge(workspaceId, value), onSuccess: (result) => { setMatches(result.chunks); setRetrievalMode(result.retrieval); }, onError: () => { setMatches([]); setRetrievalMode("Search was unavailable. Please try again."); } });
  return <div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><section className={panel}><div className="mb-4 flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-blue-700"><BookOpen size={18}/></span><div><h2 className="font-semibold text-slate-900">Workspace library</h2><p className="text-xs text-slate-500">Add trusted notes and find cited passages.</p></div></div><form className="space-y-3" onSubmit={(event) => { event.preventDefault(); onAdd({ title: title.trim(), sourceType, ...(sourceUrl.trim() ? { sourceUrl: sourceUrl.trim() } : {}), content }); setTitle(""); setSourceUrl(""); setContent(""); }}><label className="block text-xs font-semibold text-slate-500">Document title<input className={`${field} mt-1.5`} value={title} onChange={(event) => setTitle(event.target.value)} maxLength={240} required placeholder="Project requirements"/></label><label className="block text-xs font-semibold text-slate-500">Content type<select className={`${field} mt-1.5`} value={sourceType} onChange={(event) => setSourceType(event.target.value)}><option value="MARKDOWN">Markdown</option><option value="TEXT">Plain text</option><option value="URL">Pasted web content</option></select></label>{sourceType === "URL" && <label className="block text-xs font-semibold text-slate-500">Reference URL<input className={`${field} mt-1.5`} type="url" value={sourceUrl} onChange={(event) => setSourceUrl(event.target.value)} placeholder="https://example.com/docs"/></label>}<label className="block text-xs font-semibold text-slate-500">Document content<textarea className={`${field} mt-1.5 min-h-36 resize-y`} value={content} onChange={(event) => setContent(event.target.value)} minLength={20} maxLength={100000} required placeholder="Paste a short guide, decisions, or product notes…"/><span className="mt-1 block font-normal text-slate-400">Large documents are split into searchable sections. Web links are kept as references; the server does not fetch them.</span></label><button className={button} disabled={!canWrite || saving || content.trim().length < 20}><Plus size={15}/>{saving ? "Adding…" : "Add to library"}</button></form><div className="mt-6 border-t border-slate-100 pt-5"><h3 className="mb-3 text-sm font-semibold text-slate-800">Saved documents <span className="font-normal text-slate-400">({documents.length})</span></h3>{documents.length ? <div className="space-y-2">{documents.map((doc) => <div key={doc.id} className="flex items-center gap-3 rounded-xl bg-slate-50 p-3"><BookOpen size={15} className="shrink-0 text-blue-600"/><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-slate-700">{doc.title}</p><p className="mt-0.5 text-[10px] text-slate-400">{Number(doc.chunk_count)} sections · {titleCase(doc.source_type)}</p></div>{doc.source_url && <a href={doc.source_url} target="_blank" rel="noreferrer" className="text-xs font-medium text-violet-600">Source</a>}{canWrite && <button className="rounded-lg p-2 text-slate-400 hover:bg-white hover:text-rose-600" aria-label={`Delete ${doc.title}`} disabled={deleting} onClick={() => { if (window.confirm(`Delete “${doc.title}” and its searchable sections?`)) onDelete(doc.id); }}><Trash2 size={14}/></button>}</div>)}</div> : <p className="rounded-xl bg-slate-50 p-4 text-xs text-slate-500">No documents saved yet.</p>}</div></section>
    <section className={panel}><div className="mb-4 flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-violet-50 text-violet-700"><Search size={18}/></span><div><h2 className="font-semibold text-slate-900">Search the library</h2><p className="text-xs text-slate-500">{matches ? retrievalMode : "Workspace-scoped matches with source citations."}</p></div></div><form className="flex gap-2" onSubmit={(event) => { event.preventDefault(); if (query.trim().length >= 2) search.mutate(query.trim()); }}><input className={field} value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search docs, decisions, requirements…" minLength={2}/><button className={button} disabled={search.isPending || query.trim().length < 2}>{search.isPending ? <LoaderCircle size={15} className="animate-spin"/> : <Search size={15}/>}Search</button></form>{matches && <div className="mt-4 space-y-3">{matches.length ? matches.map((match) => <article key={match.chunk_id} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="text-sm font-semibold text-slate-800">{match.title}</h3>{match.heading && <p className="mt-1 text-xs font-medium text-violet-600">{match.heading}</p>}</div>{match.source_url && <a href={match.source_url} target="_blank" rel="noreferrer" className="text-xs font-semibold text-violet-600">Open source</a>}</div><p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-slate-600">{match.snippet}</p><p className="mt-2 text-[10px] text-slate-400">Citation: {match.document_id} · section {match.chunk_id}</p></article>) : <p className="rounded-xl bg-slate-50 p-5 text-center text-sm text-slate-500">No matching sections. Try different words or add documents.</p>}</div>}{!matches && <div className="mt-4 flex min-h-44 flex-col items-center justify-center rounded-xl bg-slate-50 text-center"><BookOpen size={23} className="text-slate-300"/><p className="mt-3 text-sm font-medium text-slate-600">Search results will appear here</p><p className="mt-1 text-xs text-slate-400">Workspace filters apply before ranking.</p></div>}<div className="mt-4 rounded-xl border border-slate-100 p-3 text-xs leading-5 text-slate-500">These are retrieved source passages, not AI-generated answers. Treat document text as untrusted input.</div></section></div>;
}

function IntegrationsView({ providers, integrations, events, projectId, canConnect, connecting, onConnect, syncingId, onSync, deletingId, onDelete }: { providers: IntegrationProvider[]; integrations: ExternalIntegration[]; events: IntegrationEvent[]; projectId: string; canConnect: boolean; connecting: boolean; onConnect: (payload: { provider: string; projectId: string; externalRef?: string; channelId?: string }) => void; syncingId: string | null; onSync: (id: string) => void; deletingId: string | null; onDelete: (id: string) => void }) {
  const [provider, setProvider] = useState("JIRA");
  const [externalRef, setExternalRef] = useState("");
  const [channelId, setChannelId] = useState("");
  const selectedProvider = providers.find((item) => item.provider === provider);
  const prefix = provider;
  return <div className="space-y-5">
    <section className="grid gap-5 xl:grid-cols-[.85fr_1.15fr]">
      <div className={panel}><div className="mb-4 flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-violet-50 text-violet-700"><PlugZap size={18}/></span><div><h2 className="font-semibold text-slate-900">Connect a provider</h2><p className="text-xs text-slate-500">Authorize with OAuth. Credentials stay encrypted on the server.</p></div></div>
        {canConnect ? <form className="space-y-3" onSubmit={(event) => { event.preventDefault(); onConnect({ provider, projectId, ...(externalRef.trim() ? { externalRef: externalRef.trim() } : {}), ...(channelId.trim() ? { channelId: channelId.trim() } : {}) }); }}>
          <label className="block text-xs font-semibold text-slate-500">Provider<select className={`${field} mt-1.5`} value={provider} onChange={(event) => { setProvider(event.target.value); setExternalRef(""); setChannelId(""); }} aria-label="Select integration provider">{providers.map((item) => <option key={item.provider} value={item.provider}>{item.name}</option>)}</select></label>
          {provider === "JIRA" && <label className="block text-xs font-semibold text-slate-500">Jira project key (optional)<input className={`${field} mt-1.5`} value={externalRef} onChange={(event) => setExternalRef(event.target.value.toUpperCase())} placeholder="TEAM" maxLength={30}/></label>}
          {provider === "LINEAR" && <label className="block text-xs font-semibold text-slate-500">Linear team ID (optional)<input className={`${field} mt-1.5`} value={externalRef} onChange={(event) => setExternalRef(event.target.value)} placeholder="Team UUID" maxLength={64}/></label>}
          {provider === "GITLAB" && <label className="block text-xs font-semibold text-slate-500">GitLab project ID or path (optional)<input className={`${field} mt-1.5`} value={externalRef} onChange={(event) => setExternalRef(event.target.value)} placeholder="group/project or numeric ID" maxLength={160}/><span className="mt-1 block font-normal text-slate-400">Leave blank to import issues assigned to the connected account.</span></label>}
          {provider === "SLACK" && <label className="block text-xs font-semibold text-slate-500">Slack channel ID<input className={`${field} mt-1.5`} value={channelId} onChange={(event) => setChannelId(event.target.value)} placeholder="C0123456789" maxLength={120} required/><span className="mt-1 block font-normal text-slate-400">Slack will receive a short project delivery digest when you choose Send digest.</span></label>}
          <div className="rounded-xl bg-slate-50 p-3 text-xs leading-5 text-slate-500">{selectedProvider?.purpose ?? "Connect a provider to your project."}<span className="mt-1 block">Requested access: <strong className="font-semibold text-slate-700">{selectedProvider?.scopes || "read-only"}</strong></span></div>
          <button className={button} disabled={connecting || !selectedProvider?.configured || !projectId || (provider === "SLACK" && !channelId.trim())}>{connecting ? <LoaderCircle size={15} className="animate-spin"/> : <ExternalLink size={15}/>}Connect {selectedProvider?.name ?? provider}</button>
          {!selectedProvider?.configured && <p className="text-xs leading-5 text-amber-700">This provider is not configured on the server yet. Add its OAuth client ID and secret plus <code>INTEGRATION_ENCRYPTION_KEY</code>, then restart the server.</p>}
        </form> : <div className="rounded-xl bg-slate-50 p-4 text-sm leading-6 text-slate-600">Only workspace owners and admins can connect or remove providers. Ask an owner to finish setup.</div>}
      </div>
      <div className={panel}><div className="mb-4"><h2 className="font-semibold text-slate-900">Connected accounts</h2><p className="mt-1 text-xs text-slate-500">Imports are read-only. Syncs are queued, retried, and deduplicated.</p></div>
        {integrations.length ? <div className="space-y-3">{integrations.map((item) => <article key={item.id} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><div className="flex items-center gap-2"><h3 className="font-semibold text-slate-800">{item.display_name}</h3><span className={`rounded-full px-2 py-0.5 text-[10px] font-semibold uppercase ${item.status === "ACTIVE" ? "bg-emerald-50 text-emerald-800" : item.status === "ERROR" ? "bg-rose-50 text-rose-700" : "bg-slate-100 text-slate-600"}`}>{item.status.toLowerCase()}</span></div><p className="mt-1 text-xs text-slate-500">{titleCase(item.provider)} · {item.event_count} synced items · {item.last_synced_at ? `last sync ${new Date(item.last_synced_at).toLocaleString()}` : "not synced yet"}</p>{item.latest_job_status && <p className="mt-1 text-[11px] text-slate-400">Latest job: {titleCase(item.latest_job_status)}</p>}</div><div className="flex items-center gap-2">{canConnect && <button className={subtleButton} onClick={() => onSync(item.id)} disabled={syncingId === item.id || item.latest_job_status === "PENDING" || item.latest_job_status === "PROCESSING"}>{syncingId === item.id ? <LoaderCircle size={14} className="animate-spin"/> : item.provider === "SLACK" ? <MessageSquareText size={14}/> : <RefreshCw size={14} />}{item.provider === "SLACK" ? "Send digest" : "Sync now"}</button>}{canConnect && <button className="rounded-xl border border-slate-200 p-2 text-slate-400 transition hover:bg-rose-50 hover:text-rose-600" disabled={deletingId === item.id} onClick={() => { if (window.confirm(`Remove ${item.display_name} and its synced activity?`)) onDelete(item.id); }} aria-label={`Remove ${item.display_name}`}><Trash2 size={14}/></button>}</div></div></article>)}</div> : <div className="rounded-xl bg-slate-50 p-5 text-center text-sm text-slate-500">No external accounts connected yet.</div>}
      </div>
    </section>
    <section className={panel}><div className="mb-4"><h2 className="font-semibold text-slate-900">Recent external activity</h2><p className="mt-1 text-xs text-slate-500">Linked provider events stored against this project.</p></div>{events.length ? <div className="divide-y divide-slate-100">{events.slice(0, 30).map((event) => <div key={event.id} className="flex items-start gap-3 py-3 first:pt-0 last:pb-0"><span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-violet-500"/><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="truncate text-sm font-medium text-slate-700">{event.title}</p><span className="rounded-full bg-slate-100 px-2 py-0.5 text-[10px] font-semibold uppercase text-slate-500">{titleCase(event.provider)}</span></div><p className="mt-1 text-xs text-slate-500">{event.body ? `${event.body} · ` : ""}{event.actor ? `${event.actor} · ` : ""}{new Date(event.occurred_at).toLocaleString()}</p></div>{event.url && <a className="text-slate-400 hover:text-violet-600" href={event.url} target="_blank" rel="noreferrer" aria-label="Open provider item"><ExternalLink size={15}/></a>}</div>)}</div> : <p className="rounded-xl bg-slate-50 p-5 text-center text-sm text-slate-500">No synced activity yet. Run a sync to import recent issues.</p>}</section>
    <details className={panel}><summary className="cursor-pointer font-semibold text-slate-800">Configure OAuth apps on the server</summary><div className="mt-3 space-y-2 text-xs leading-5 text-slate-500"><p>Register this callback URL in each provider app, then configure server environment values:</p><ul className="list-inside list-disc space-y-1"><li><code>{prefix}_CLIENT_ID</code>, <code>{prefix}_CLIENT_SECRET</code>, and optional <code>{prefix}_REDIRECT_URI</code></li><li><code>PUBLIC_SERVER_URL</code> must be the public HTTPS origin in deployment.</li><li><code>INTEGRATION_ENCRYPTION_KEY</code> must be a private random value of at least 32 characters; keep the same value across server restarts.</li><li>Restart the API and integration worker after changing credentials. Provider scopes are read-only for Jira, Linear, and GitLab; Slack only requests <code>chat:write</code>.</li></ul><p>The active callback for {selectedProvider?.name ?? provider}: <code className="break-all">{selectedProvider?.callbackUrl}</code></p></div></details>
  </div>;
}

export default function IntelligencePage() {
  const { currentWorkspace, setCurrentWorkspace, workspaces } = useWorkspace();
  const workspaceId = currentWorkspace?.id ?? "";
  const { data: projects = [] } = useProjects(workspaceId || null);
  const [searchParams, setSearchParams] = useSearchParams();
  const [projectId, setProjectId] = useState("");
  const [tab, setTab] = useState<Tab>(() => searchParams.get("tab") === "integrations" || searchParams.has("integration") ? "integrations" : "analytics");
  const [notice, setNotice] = useState(() => {
    const result = searchParams.get("integration");
    return result ? result === "connected" ? "Provider connected. You can now queue a sync." : "Provider connection did not complete. Check the provider setup and try again." : "";
  });
  const queryClient = useQueryClient();
  const oauthResult = searchParams.get("integration");
  const oauthWorkspaceId = searchParams.get("workspaceId");
  useEffect(() => {
    if (oauthWorkspaceId) {
      const targetWorkspace = workspaces.find((workspace) => workspace.id === oauthWorkspaceId);
      if (targetWorkspace && targetWorkspace.id !== currentWorkspace?.id) setCurrentWorkspace(targetWorkspace);
    }
    if (oauthResult) {
      setSearchParams((previous) => { const next = new URLSearchParams(previous); next.delete("integration"); next.delete("workspaceId"); next.delete("tab"); return next; }, { replace: true });
    }
  }, [oauthResult, oauthWorkspaceId, workspaces, currentWorkspace?.id, setCurrentWorkspace, setSearchParams]);
  const selectedProjectId = projects.some((project) => project.id === projectId) ? projectId : projects[0]?.id ?? "";
  const canWrite = currentWorkspace?.role !== "VIEWER";
  const tasksQuery = useTasks(workspaceId || null, selectedProjectId || null);
  const graph = useQuery({ queryKey: ["execution-graph", workspaceId, selectedProjectId], queryFn: () => getExecutionGraph(workspaceId, selectedProjectId), enabled: Boolean(workspaceId && selectedProjectId) });
  const analytics = useQuery({ queryKey: ["execution-analytics", workspaceId, selectedProjectId], queryFn: () => getAnalytics(workspaceId, selectedProjectId), enabled: Boolean(workspaceId && selectedProjectId) });
  const scenarios = useQuery({ queryKey: ["execution-scenarios", workspaceId, selectedProjectId], queryFn: () => getScenarios(workspaceId, selectedProjectId), enabled: Boolean(workspaceId && selectedProjectId) });
  const recovery = useQuery({ queryKey: ["recovery-plans", workspaceId, selectedProjectId], queryFn: () => getRecoveryPlans(workspaceId, selectedProjectId), enabled: Boolean(workspaceId && selectedProjectId) });
  const runs = useQuery({ queryKey: ["agent-runs", workspaceId, selectedProjectId], queryFn: () => getAgentRuns(workspaceId, selectedProjectId), enabled: Boolean(workspaceId && selectedProjectId) });
  const documents = useQuery({ queryKey: ["knowledge-documents", workspaceId], queryFn: () => getKnowledgeDocuments(workspaceId), enabled: Boolean(workspaceId) });
  const providers = useQuery({ queryKey: ["integration-providers", workspaceId], queryFn: () => getIntegrationProviders(workspaceId), enabled: Boolean(workspaceId) });
  const integrations = useQuery({ queryKey: ["external-integrations", workspaceId], queryFn: () => getIntegrations(workspaceId), enabled: Boolean(workspaceId), refetchInterval: (query) => query.state.data?.some((item) => item.latest_job_status === "PENDING" || item.latest_job_status === "PROCESSING") ? 3000 : false });
  const integrationEvents = useQuery({ queryKey: ["external-integration-events", workspaceId, selectedProjectId], queryFn: () => getIntegrationEvents(workspaceId, selectedProjectId), enabled: Boolean(workspaceId && selectedProjectId), refetchInterval: integrations.data?.some((item) => item.latest_job_status === "PENDING" || item.latest_job_status === "PROCESSING") ? 3000 : false });
  const snapshot = useMutation({ mutationFn: () => saveAnalyticsSnapshot(workspaceId, selectedProjectId), onSuccess: () => setNotice("Analytics snapshot saved.") });
  const addScenario = useMutation({ mutationFn: (payload: { name: string; changes: Record<string, unknown> }) => createScenario(workspaceId, selectedProjectId, payload), onSuccess: async () => { setNotice("Scenario saved. Run it to calculate the schedule impact."); await queryClient.invalidateQueries({ queryKey: ["execution-scenarios", workspaceId, selectedProjectId] }); }, onError: (error: Error) => setNotice(error.message) });
  const scenarioRun = useMutation({ mutationFn: (id: string) => runScenario(workspaceId, selectedProjectId, id), onSuccess: async () => { setNotice("Scenario simulated without changing project tasks."); await queryClient.invalidateQueries({ queryKey: ["execution-scenarios", workspaceId, selectedProjectId] }); }, onError: (error: Error) => setNotice(error.message) });
  const recoveryCreate = useMutation({ mutationFn: () => createRecoveryPlan(workspaceId, selectedProjectId), onSuccess: async () => { setNotice("Recovery options are ready for review."); await queryClient.invalidateQueries({ queryKey: ["recovery-plans", workspaceId, selectedProjectId] }); }, onError: (error: Error) => setNotice(error.message) });
  const recoveryDecision = useMutation({ mutationFn: (input: { planId: string; decision: "APPROVE" | "REJECT"; optionKey?: string }) => decideRecoveryPlan(workspaceId, selectedProjectId, input.planId, { decision: input.decision, optionKey: input.optionKey }), onSuccess: async (plan) => { setNotice(plan.status === "QUEUED" ? "Approved. The recovery worker will apply and verify the selected action." : "Recovery plan rejected."); await queryClient.invalidateQueries({ queryKey: ["recovery-plans", workspaceId, selectedProjectId] }); }, onError: (error: Error) => setNotice(error.message) });
  const agentRun = useMutation({ mutationFn: (payload: { agentType: string; budgetLimit: number; question?: string }) => runAgent(workspaceId, selectedProjectId, payload), onSuccess: async () => { setNotice("Agent run saved with trace and citations."); await queryClient.invalidateQueries({ queryKey: ["agent-runs", workspaceId, selectedProjectId] }); }, onError: (error: Error) => setNotice(error.message) });
  const addDocument = useMutation({ mutationFn: (payload: { title: string; sourceType: string; sourceUrl?: string; content: string }) => addKnowledgeDocument(workspaceId, payload), onSuccess: async (result) => { setNotice(result.message); await queryClient.invalidateQueries({ queryKey: ["knowledge-documents", workspaceId] }); }, onError: (error: Error) => setNotice(error.message) });
  const deleteDocument = useMutation({ mutationFn: (id: string) => deleteKnowledgeDocument(workspaceId, id), onSuccess: async () => { setNotice("Document and its indexed sections were deleted."); await queryClient.invalidateQueries({ queryKey: ["knowledge-documents", workspaceId] }); }, onError: (error: Error) => setNotice(error.message) });
  const startProvider = useMutation({ mutationFn: (payload: { provider: string; projectId: string; externalRef?: string; channelId?: string }) => startIntegration(workspaceId, payload.provider, payload), onSuccess: (result) => { window.location.assign(result.authorizationUrl); }, onError: (error: Error) => setNotice(error.message) });
  const syncProvider = useMutation({ mutationFn: (id: string) => queueIntegrationSync(workspaceId, id), onSuccess: async ({ message }) => { setNotice(message); await queryClient.invalidateQueries({ queryKey: ["external-integrations", workspaceId] }); }, onError: (error: Error) => setNotice(error.message) });
  const removeProvider = useMutation({ mutationFn: (id: string) => deleteIntegration(workspaceId, id), onSuccess: async () => { setNotice("Integration removed; its linked activity was deleted."); await Promise.all([queryClient.invalidateQueries({ queryKey: ["external-integrations", workspaceId] }), queryClient.invalidateQueries({ queryKey: ["external-integration-events", workspaceId] })]); }, onError: (error: Error) => setNotice(error.message) });
  const availableTasks = useMemo(() => graph.data?.tasks.map((task) => ({ id: task.id, title: task.title })) ?? tasksQuery.data?.map((task) => ({ id: task.id, title: task.title })) ?? [], [graph.data?.tasks, tasksQuery.data]);
  const canConnectProviders = currentWorkspace?.role === "OWNER" || currentWorkspace?.role === "ADMIN";

  if (!currentWorkspace) return <div className="p-8 text-sm text-slate-500">Select a workspace to use project intelligence.</div>;
  if (!projects.length) return <div className={`${panel} mx-auto max-w-3xl py-10 text-center`}><BrainCircuit size={28} className="mx-auto text-violet-500"/><h1 className="mt-3 text-xl font-bold text-slate-900">Project intelligence</h1><p className="mt-2 text-sm text-slate-500">Create a project and tasks to see execution analytics and scenarios.</p></div>;

  return <div className="mx-auto max-w-7xl space-y-5 pb-8">
    <header className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><div className="mb-2 flex items-center gap-2 text-xs font-semibold uppercase tracking-[.16em] text-violet-600"><Sparkles size={14}/>Team intelligence</div><h1 className="text-3xl font-bold tracking-tight text-slate-950">Project insights</h1><p className="mt-1 max-w-2xl text-sm text-slate-500">Understand delivery, compare schedule changes, and review evidence with clear approvals.</p></div><label className="flex flex-col gap-1.5 text-xs font-semibold text-slate-500">Project<select className="min-w-60 rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-medium text-slate-800" value={selectedProjectId} onChange={(event) => setProjectId(event.target.value)} aria-label="Select project">{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select></label></header>
    {notice && <div role="status" className="rounded-xl border border-violet-200 bg-violet-50 px-4 py-3 text-sm text-violet-800">{notice}<button className="ml-3 font-semibold underline" onClick={() => setNotice("")}>Dismiss</button></div>}
    <nav aria-label="Project intelligence sections" className="flex gap-1 overflow-x-auto rounded-2xl border border-slate-200 bg-white p-1.5 shadow-sm">{tabs.map(({ id, label, icon: Icon }) => <button key={id} className={`inline-flex shrink-0 items-center gap-2 rounded-xl px-3 py-2.5 text-sm font-semibold transition ${tab === id ? "bg-violet-600 text-white shadow-sm" : "text-slate-500 hover:bg-slate-50 hover:text-slate-800"}`} onClick={() => setTab(id)}><Icon size={15}/>{label}</button>)}</nav>
    {tab === "analytics" && (analytics.isLoading ? <div className={`${panel} py-10 text-center text-sm text-slate-500`}>Loading execution analytics…</div> : analytics.data ? <AnalyticsView analytics={analytics.data} saving={snapshot.isPending} onSave={() => snapshot.mutate()}/> : <div className={`${panel} py-8 text-center text-sm text-rose-600`}>Could not load analytics. {analytics.error instanceof Error ? analytics.error.message : "Try refreshing."}</div>)}
    {tab === "scenarios" && <ScenarioView scenarios={scenarios.data ?? []} tasks={availableTasks} canWrite={canWrite} onCreate={(payload) => addScenario.mutate(payload)} creating={addScenario.isPending} onRun={(id) => scenarioRun.mutate(id)} runningId={scenarioRun.isPending ? scenarioRun.variables : null}/>}
    {tab === "recovery" && <RecoveryView plans={recovery.data ?? []} canWrite={canWrite} creating={recoveryCreate.isPending} onCreate={() => recoveryCreate.mutate()} onDecision={(value) => recoveryDecision.mutate(value)}/>}
    {tab === "agents" && <AgentsView runs={runs.data ?? []} canWrite={canWrite} running={agentRun.isPending} onRun={(payload) => agentRun.mutate(payload)}/>}
    {tab === "knowledge" && <KnowledgeView workspaceId={workspaceId} documents={documents.data ?? []} canWrite={canWrite} saving={addDocument.isPending} deleting={deleteDocument.isPending} onAdd={(payload) => addDocument.mutate(payload)} onDelete={(id) => deleteDocument.mutate(id)}/>}
    {tab === "integrations" && <IntegrationsView providers={providers.data ?? []} integrations={integrations.data ?? []} events={integrationEvents.data ?? []} projectId={selectedProjectId} canConnect={canConnectProviders} connecting={startProvider.isPending} onConnect={(payload) => startProvider.mutate(payload)} syncingId={syncProvider.isPending ? syncProvider.variables : null} onSync={(id) => syncProvider.mutate(id)} deletingId={removeProvider.isPending ? removeProvider.variables : null} onDelete={(id) => removeProvider.mutate(id)}/>}
    {analytics.isError && tab !== "analytics" && <p className="text-xs text-slate-400">Analytics may need a valid, cycle-free task dependency graph.</p>}
  </div>;
}
